保存前检查表。ok 为 false 就停，不要点保存：(() => {
  const S = (el) => ((el && (el.innerText || el.textContent)) || "").replace(/\s+/g, " ").trim();
  const fi = (kw) => [...document.querySelectorAll(".ant-form-item")].find((f) => S(f.querySelector("label")).replace(/\s+/g, "").includes(kw));
  const val = (el) => (el ? String(el.value ?? "").trim() : "");
  const cjk = (s) => (String(s).match(/[\u4e00-\u9fff]/g) || []).length;
  const letters = (s) => (String(s).match(/[A-Za-z]/g) || []).length;
  const fails = [];
  const title = val((fi("产品标题") || {}).querySelector && fi("产品标题").querySelector("input,textarea"));
  if (!title) fails.push("标题为空");
  else if (cjk(title) > 0 && cjk(title) >= letters(title)) fails.push("标题仍含中文");
  const imgs = [...document.querySelectorAll(".productMainImgModule .single-image")];
  const checked = imgs.filter((el) => el.querySelector("input.ant-checkbox-input")?.checked).length;
  if (checked !== 6) fails.push("主图 " + checked + " 张，需要恰好 6 张");
  const bad = imgs.filter((el) => {
    const m = S(el).match(/(\d{2,4})\s*[Xx×]\s*(\d{2,4})/);
    const nw = el.querySelector("img")?.naturalWidth || 0;
    return !(m && Number(m[1]) === 800 && (nw === 0 || nw === 800));
  });
  if (!imgs.length || bad.length) fails.push("商品图不是全部 800 宽");
  const attrs = fi("自定义属性") ? [...fi("自定义属性").querySelectorAll("input,textarea")].map((el) => el.value) : [];
  if (attrs.reduce((n, v) => n + cjk(v), 0) > 0) fails.push("自定义属性有中文");
  const errs = [...document.querySelectorAll(".ant-form-item-explain-error")].map(S).filter(Boolean);
  const dutyOn = fi("报价是否含关税") ? [...fi("报价是否含关税").querySelectorAll("input[type=radio]")].some((r) => r.checked) : false;
  if (errs.length || !dutyOn) fails.push(errs[0] || "报价是否含关税未选");
  const rows = [...document.querySelectorAll(".smtSkuEditTable table tr")].slice(2);
  let empty = 0;
  rows.forEach((tr) => {
    const td = [...tr.querySelectorAll("td")];
    if (!val(td[2] && td[2].querySelector("input")) || !val(td[6] && td[6].querySelector("input"))) empty += 1;
  });
  if (!rows.length || empty) fails.push("SKU 有空的价格或库存");
  const cat = (fi("产品分类") ? S(fi("产品分类")) : "").replace(/^产品分类/, "").trim();
  if (cat.length < 2) fails.push("类目为空");
  return { ok: fails.length === 0, fails };
})()
